from abc import ABC, abstractmethod


class FilterStrategy(ABC):
    @abstractmethod
    def should_include(self, item) -> bool:
        pass


class TransformStrategy(ABC):
    @abstractmethod
    def transform(self, item):
        pass


class PassThroughFilter(FilterStrategy):
    def should_include(self, item) -> bool:
        return True


class PassThroughTransform(TransformStrategy):
    def transform(self, item):
        return item


class CachedTransform(TransformStrategy):
    def __init__(self, delegate: TransformStrategy):
        self._delegate = delegate
        self._cache = {}

    def _get_key(self, item):
        if isinstance(item, (str, int, float, bool, bytes, tuple)):
            return item
        if isinstance(item, dict):
            return tuple(sorted(item.items()))
        return id(item)

    def transform(self, item):
        key = self._get_key(item)
        if key in self._cache:
            return self._cache[key]
        result = self._delegate.transform(item)
        self._cache[key] = result
        return result

    def clear_cache(self):
        self._cache.clear()


class DataProcessor:
    def __init__(self, filter_strategy: FilterStrategy = None, transform_strategy: TransformStrategy = None):
        self.filter_strategy = filter_strategy or PassThroughFilter()
        self.transform_strategy = transform_strategy or PassThroughTransform()

    def process(self, data):
        result = []
        for item in data:
            if not self.filter_strategy.should_include(item):
                continue
            result.append(self.transform_strategy.transform(item))
        return result

    def clear_cache(self):
        if isinstance(self.transform_strategy, CachedTransform):
            self.transform_strategy.clear_cache()

